1	/**
2	 * Server-side execution logic for the Hermes Agent adapter.
3	 *
4	 * Spawns `hermes chat -q "..." -Q` as a child process, streams output,
5	 * and returns structured results to Paperclip.
6	 *
7	 * Verified CLI flags (hermes chat):
8	 *   -q/--query         single query (non-interactive)
9	 *   -Q/--quiet         quiet mode (no banner/spinner, only response + session_id)
10	 *   -m/--model         model name (e.g. anthropic/claude-sonnet-4)
11	 *   -t/--toolsets      comma-separated toolsets to enable
12	 *   --provider         inference provider (auto, openrouter, nous, etc.)
13	 *   -r/--resume        resume session by ID
14	 *   -w/--worktree      isolated git worktree
15	 *   -v/--verbose       verbose output
16	 *   --checkpoints      filesystem checkpoints
17	 */
18	import { runChildProcess, buildPaperclipEnv, renderTemplate, ensureAbsoluteDirectory, } from "@paperclipai/adapter-utils/server-utils";
19	import { HERMES_CLI, DEFAULT_TIMEOUT_SEC, DEFAULT_GRACE_SEC, VALID_PROVIDERS, } from "../shared/constants.js";
20	// ---------------------------------------------------------------------------
21	// Config helpers
22	// ---------------------------------------------------------------------------
23	function cfgString(v) {
24	    return typeof v === "string" && v.length > 0 ? v : undefined;
25	}
26	function cfgNumber(v) {
27	    return typeof v === "number" ? v : undefined;
28	}
29	function cfgBoolean(v) {
30	    return typeof v === "boolean" ? v : undefined;
31	}
32	function cfgStringArray(v) {
33	    return Array.isArray(v) && v.every((i) => typeof i === "string")
34	        ? v
35	        : undefined;
36	}
37	// ---------------------------------------------------------------------------
38	// Wake-up prompt builder
39	// ---------------------------------------------------------------------------
